-- Remove only wording generated by the application. Keep user text and counting data intact.
UPDATE events
SET name = substring(name FROM char_length('DÉMONSTRATION — ') + 1),
    description = 'Événement créé publiquement. Nom, commune et périmètre déclarés par le créateur, sans vérification indépendante de leur correspondance.',
    metadata_version = metadata_version + 1,
    updated_at = clock_timestamp()
WHERE is_test = true
  AND creation_source = 'community'
  AND left(name, char_length('DÉMONSTRATION — ')) = 'DÉMONSTRATION — '
  AND description = 'Démonstration fictive créée publiquement. Ce lieu et ce périmètre sont déclarés par le créateur ; ils ne certifient aucune manifestation réelle.';

UPDATE events AS event
SET name = 'Place de la République',
    description = 'Zone de comptage située place de la République à Paris.',
    metadata_version = metadata_version + 1,
    updated_at = clock_timestamp()
WHERE event.is_test = true
  AND event.creation_source = 'team'
  AND event.slug LIKE 'demonstration-republique-%'
  AND event.name = 'DÉMONSTRATION FICTIVE — Place de la République'
  AND event.description = 'Événement de test fictif. Ces participations ne mesurent aucune manifestation réelle. La zone de démonstration se situe place de la République à Paris.'
  AND EXISTS (
    SELECT 1 FROM admin_audit AS audit
    WHERE audit.event_id = event.id
      AND audit.action = 'import_draft'
      AND audit.reason = 'Création explicite d’une démonstration fictive, sans présence initiale'
  );
